-- Samlede bookinger (ordrer) med flere maskiner, kunderabatter og rabatkoder.
-- Rent additiv og idempotent: eksisterende tabeller og data ændres ikke, der kommer kun nye tabeller/kolonner til.

CREATE TABLE IF NOT EXISTS "booking_order" (
  "id" text PRIMARY KEY,
  "orderNumber" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1001) UNIQUE,
  "userId" text NOT NULL,
  "customerName" text NOT NULL,
  "customerEmail" text NOT NULL,
  "customerPhone" text NOT NULL,
  "company" text,
  "notes" text,
  "deliveryType" text NOT NULL DEFAULT 'collection',
  "deliveryAddress" text,
  "deliveryPostalCode" text,
  "deliveryFee" integer NOT NULL DEFAULT 0,
  "subtotal" integer NOT NULL DEFAULT 0,
  "discountAmount" integer NOT NULL DEFAULT 0,
  "discountLabel" text,
  "discountCodeId" text,
  "total" integer NOT NULL DEFAULT 0,
  "deposit" integer NOT NULL DEFAULT 0,
  "status" text NOT NULL DEFAULT 'pending',
  "createdAt" timestamp NOT NULL DEFAULT now(),
  "updatedAt" timestamp NOT NULL DEFAULT now(),
  CONSTRAINT "booking_order_status_valid" CHECK ("status" IN ('pending','confirmed','cancelled')),
  CONSTRAINT "booking_order_delivery_valid" CHECK ("deliveryType" IN ('collection','delivery')),
  CONSTRAINT "booking_order_amounts_valid" CHECK ("deliveryFee" >= 0 AND "subtotal" >= 0 AND "discountAmount" >= 0 AND "discountAmount" <= "subtotal" AND "total" >= 0 AND "deposit" >= 0)
);
CREATE INDEX IF NOT EXISTS "booking_order_user_idx" ON "booking_order" ("userId");
CREATE INDEX IF NOT EXISTS "booking_order_created_idx" ON "booking_order" ("createdAt" DESC);

ALTER TABLE "booking" ADD COLUMN IF NOT EXISTS "orderId" text;
CREATE INDEX IF NOT EXISTS "booking_order_id_idx" ON "booking" ("orderId");

CREATE TABLE IF NOT EXISTS "customer_discount" (
  "userId" text PRIMARY KEY,
  "percent" integer NOT NULL DEFAULT 0,
  "note" text,
  "updatedAt" timestamp NOT NULL DEFAULT now(),
  CONSTRAINT "customer_discount_percent_valid" CHECK ("percent" BETWEEN 0 AND 100)
);

CREATE TABLE IF NOT EXISTS "discount_code" (
  "id" text PRIMARY KEY,
  "code" text NOT NULL UNIQUE,
  "kind" text NOT NULL,
  "value" integer NOT NULL,
  "minSubtotal" integer NOT NULL DEFAULT 0,
  "validFrom" date,
  "validUntil" date,
  "maxUses" integer,
  "usedCount" integer NOT NULL DEFAULT 0,
  "active" boolean NOT NULL DEFAULT true,
  "note" text,
  "createdAt" timestamp NOT NULL DEFAULT now(),
  "updatedAt" timestamp NOT NULL DEFAULT now(),
  CONSTRAINT "discount_code_kind_valid" CHECK ("kind" IN ('percent','amount')),
  CONSTRAINT "discount_code_value_valid" CHECK ("value" > 0 AND ("kind" <> 'percent' OR "value" <= 100)),
  CONSTRAINT "discount_code_uses_valid" CHECK ("usedCount" >= 0 AND ("maxUses" IS NULL OR "maxUses" >= 1)),
  CONSTRAINT "discount_code_dates_valid" CHECK ("validFrom" IS NULL OR "validUntil" IS NULL OR "validUntil" >= "validFrom")
);
